<template>
  <div class="business-config-container">
    <el-page-header @back="$router.push('/')">
      <template #content>
        <span class="font-weight-bold">业务配置中心</span>
      </template>
    </el-page-header>

    <div class="steps-wrapper mt-6">
      <el-steps :active="activeStep" finish-status="success" align-center>
        <el-step title="应用定义" description="设置名称与编码" />
        <el-step title="配置表单" description="设计动态字段" />
        <el-step title="配置流程" description="定义审批节点" />
        <el-step title="配置规则" description="设置自动化动作" />
        <el-step title="发布业务" description="立即生效上线" />
      </el-steps>
    </div>

    <el-card class="mt-6 config-card">
      <!-- Step 1: 应用定义 -->
      <div v-if="activeStep === 0" class="step-content">
        <el-form :model="appForm" label-width="100px" style="max-width: 500px; margin: 0 auto">
          <el-form-item label="应用名称" required>
            <el-input v-model="appForm.name" placeholder="如：会议室预订" />
          </el-form-item>
          <el-form-item label="应用编码" required>
            <el-input v-model="appForm.code" placeholder="如：meeting_room (唯一标识)" />
          </el-form-item>
          <el-form-item label="图标" required>
            <el-select v-model="appForm.icon" placeholder="选择展示图标" style="width: 100%">
              <el-option label="日历 (Calendar)" value="Calendar" />
              <el-option label="盒子 (Box)" value="Box" />
              <el-option label="文档 (Document)" value="Document" />
              <el-option label="闹钟 (AlarmClock)" value="AlarmClock" />
              <el-option label="地点 (Location)" value="Location" />
            </el-select>
          </el-form-item>
          <el-form-item label="描述">
            <el-input v-model="appForm.description" type="textarea" rows="3" />
          </el-form-item>
        </el-form>
      </div>

      <!-- Step 2: 配置表单 -->
      <div v-if="activeStep === 1" class="step-content full-width">
        <div class="form-designer">
          <div class="designer-left">
            <h4>字段库</h4>
            <div class="field-items">
            <div v-for="ft in fieldTypes" :key="ft.type" class="field-item" @click="addField(ft)">
              <el-icon class="mr-1">
                <component :is="ft.icon || Plus" />
              </el-icon>
              {{ ft.label }}
            </div>
            </div>
          </div>
          <div class="designer-main">
            <h4>表单预览 (点击编辑属性)</h4>
            <el-empty v-if="fields.length === 0" description="请从左侧点击添加字段" />
            <div v-for="(field, index) in fields" :key="index" 
                 class="field-preview-item" 
                 :class="{ active: selectedFieldIndex === index }"
                 @click="selectedFieldIndex = index">
              <div class="field-header">
                <span class="field-label">{{ field.field_label }} <span v-if="field.required" class="required">*</span></span>
                <el-button link type="danger" @click.stop="removeField(index)"><el-icon><Delete /></el-icon></el-button>
              </div>
              <el-input v-if="field.field_type === 'text'" disabled placeholder="文本输入框" />
              <el-input v-if="field.field_type === 'user_name'" disabled placeholder="自动获取学生姓名" />
              <el-input-number v-if="field.field_type === 'number'" disabled style="width: 100%" />
              <el-date-picker v-if="field.field_type === 'date'" disabled style="width: 100%" />
              <el-select v-if="field.field_type === 'select'" disabled placeholder="下拉选择" style="width: 100%" />
            </div>
          </div>
          <div class="designer-right">
            <h4>字段属性</h4>
            <el-form v-if="selectedField" label-position="top">
              <el-form-item label="显示名称">
                <el-input v-model="selectedField.field_label" />
              </el-form-item>
              <el-form-item label="字段编码">
                <el-input v-model="selectedField.field_name" />
              </el-form-item>
              <el-form-item label="是否必填">
                <el-switch v-model="selectedField.required" />
              </el-form-item>
              <el-form-item label="默认值">
                <el-input v-model="selectedField.default_value" />
              </el-form-item>
              <el-form-item v-if="selectedField.field_type === 'select'" label="下拉选项">
                <div class="options-editor">
                  <div v-for="(opt, oi) in getFieldOptions(selectedFieldIndex)" :key="oi" class="option-row">
                    <el-input v-model="opt.label" placeholder="显示文本" style="flex: 1; margin-right: 4px" @change="() => { if(!opt.value || opt.value === 'option'+(oi+1)) opt.value = opt.label }" />
                    <el-input v-model="opt.value" placeholder="值" style="width: 100px; margin-right: 4px" />
                    <el-button link type="danger" @click="removeFieldOption(selectedFieldIndex, oi)"><el-icon><Delete /></el-icon></el-button>
                  </div>
                  <el-button type="primary" plain size="small" @click="addFieldOption(selectedFieldIndex)">
                    <el-icon class="mr-1"><Plus /></el-icon>添加选项
                  </el-button>
                </div>
              </el-form-item>
            </el-form>
            <p v-else class="hint">请选择字段进行配置</p>
          </div>
        </div>
      </div>

      <!-- Step 3: 配置流程 -->
      <div v-if="activeStep === 2" class="step-content">
        <div class="flow-designer">
          
          <div class="flow-nodes mt-4">
            <div class="flow-node start">开始 (提交人)</div>
            <div class="flow-arrow"><el-icon><Bottom /></el-icon></div>
            <div v-for="(node, index) in flowNodes" :key="index" class="flow-node-wrapper">
              <div class="flow-node approve" @click="editFlowNode(index)">
                <span>{{ node.name }}</span>
                <div class="node-badges" v-if="node.approver || node.condition">
                  <el-tag v-if="node.approver" size="small" type="info">审批人ID: {{ node.approver }}</el-tag>
                  <el-tag v-if="node.condition" size="small" type="warning">{{ node.condition }}</el-tag>
                </div>
                <el-button link type="danger" @click.stop="removeFlowNode(index)"><el-icon><Close /></el-icon></el-button>
              </div>
              <div class="flow-arrow"><el-icon><Bottom /></el-icon></div>
            </div>
            <el-button type="dashed" @click="addFlowNode" class="add-node-btn">
              <el-icon><Plus /></el-icon> 添加审批节点
            </el-button>
            <div class="flow-arrow"><el-icon><Bottom /></el-icon></div>
            <div class="flow-node end">结束</div>
          </div>
        </div>
      </div>

      <!-- Step 4: 配置规则 -->
      <div v-if="activeStep === 3" class="step-content">
        <el-table :data="rules" stripe>
          <el-table-column prop="name" label="规则名称" />
          <el-table-column prop="trigger_type" label="触发时机" />
          <el-table-column prop="action_type" label="动作类型" />
          <el-table-column label="操作" width="100">
            <template #default="{ $index }">
              <el-button link type="danger" @click="rules.splice($index, 1)">删除</el-button>
            </template>
          </el-table-column>
        </el-table>
        <el-button type="primary" plain class="mt-4" @click="addRule">
          <el-icon class="mr-1"><Plus /></el-icon> 添加自动化规则
        </el-button>
      </div>

      <!-- Step 5: 发布业务 -->
      <div v-if="activeStep === 4" class="step-content text-center">
        <el-result icon="success" title="业务配置已就绪" sub-title="点击下方按钮，系统将自动生成底层元数据并立即发布。">
          <template #extra>
            <el-button type="primary" size="large" :loading="publishing" @click="handlePublish">发布业务</el-button>
          </template>
        </el-result>
      </div>

      <div class="card-footer mt-6" v-if="activeStep < 4">
        <el-button :disabled="activeStep === 0" @click="activeStep--">上一步</el-button>
        <el-button type="primary" @click="nextStep">下一步</el-button>
      </div>
    </el-card>

    <!-- 流程节点编辑对话框 -->
    <el-dialog v-model="flowNodeDialogVisible" title="编辑审批节点" width="500px">
      <el-form :model="editingNode" label-width="100px">
        <el-form-item label="节点名称">
          <el-input v-model="editingNode.name" />
        </el-form-item>
        <el-form-item label="指定审批人">
          <el-select v-model="editingNode.approver" placeholder="不指定（由申请人选择）" clearable filterable style="width: 100%">
            <el-option label="不指定" :value="null" />
            <el-option
              v-for="user in availableApprovers"
              :key="user.id"
              :label="`${user.name} (${user.username || ''})`"
              :value="user.id"
            />
          </el-select>
        </el-form-item>
        <el-form-item label="条件表达式">
          <el-input v-model="editingNode.condition" placeholder="如：days > 3（为空表示无条件）" />
          <div class="form-tip">条件满足时停在此节点；不满足时自动跳过。例如：days > 3 表示借用天数大于3天才需要此审批环节</div>
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="flowNodeDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="saveFlowNode">确认</el-button>
      </template>
    </el-dialog>

    <!-- 规则配置对话框 -->
    <el-dialog v-model="ruleDialogVisible" title="配置规则" width="500px">
      <el-form :model="currentRule" label-width="100px">
        <el-form-item label="规则名称">
          <el-input v-model="currentRule.name" />
        </el-form-item>
        <el-form-item label="触发时机">
          <el-select v-model="currentRule.trigger_type" style="width: 100%">
            <el-option label="提交时" value="on_submit" />
            <el-option label="批准时" value="on_approve" />
            <el-option label="驳回时" value="on_reject" />
            <el-option label="完成时" value="on_complete" />
          </el-select>
        </el-form-item>
        <el-form-item label="动作类型">
          <el-select v-model="currentRule.action_type" style="width: 100%">
            <el-option label="发消息" value="send_message" />
            <el-option label="更新库存(借用业务)" value="update_field" />
          </el-select>
        </el-form-item>
        <el-form-item v-if="currentRule.action_type === 'send_message'" label="消息内容">
          <el-input v-model="currentRule.message_content" placeholder="如：您的申请已通过" />
        </el-form-item>
        <el-form-item v-if="currentRule.action_type === 'update_field'" label="更新配置">
          <el-alert title="将自动关联表单中的 equipment_id 字段进行减库存操作" type="info" :closable="false" />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="ruleDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="saveRule">确认</el-button>
      </template>
    </el-dialog>

    <el-dialog v-model="customFieldDialogVisible" title="自定义字段" width="520px">
      <el-form :model="customField" label-width="100px">
        <el-form-item label="字段名称" required>
          <el-input v-model="customField.label" placeholder="如：会议主题" />
        </el-form-item>
        <el-form-item label="字段编码" required>
          <el-input v-model="customField.name" placeholder="如：meeting_topic" />
        </el-form-item>
        <el-form-item label="字段类型" required>
          <el-select v-model="customField.type" style="width: 100%">
            <el-option label="单行文本" value="text" />
            <el-option label="多行文本" value="textarea" />
            <el-option label="数字" value="number" />
            <el-option label="日期" value="date" />
            <el-option label="下拉选择" value="select" />
            <el-option label="图片" value="file" />
            <el-option label="设备选择" value="equipment_select" />
            <el-option label="导师审核" value="approver_teacher" />
          </el-select>
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="customFieldDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="saveCustomField">确认</el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script setup>
import { ref, reactive, computed } from 'vue'
import { Plus, Delete, Bottom, Close, PictureFilled, UserFilled, EditPen } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import api from '@/api'
import { useRouter } from 'vue-router'

const router = useRouter()
const activeStep = ref(0)
const publishing = ref(false)

// Step 1 Data
const appForm = reactive({
  name: '',
  code: '',
  icon: 'Document',
  description: ''
})

// Step 2 Data
const fields = ref([])
const selectedFieldIndex = ref(-1)
const fieldTypes = [
  { label: '单行文本', type: 'text', icon: EditPen },
  { label: '数字', type: 'number', icon: EditPen },
  { label: '日期选择', type: 'date', icon: EditPen },
  { label: '下拉选择', type: 'select', icon: EditPen },
  { label: '多行文本', type: 'textarea', icon: EditPen },
  { label: '图片', type: 'file', icon: PictureFilled },
  { label: '学生姓名(自动)', type: 'user_name', icon: UserFilled },
  { label: '导师审核', type: 'approver_teacher', icon: UserFilled },
  { label: '设备选择', type: 'equipment_select', icon: EditPen },
  { label: '自定义字段', type: 'custom', icon: Plus }
]
const selectedField = computed(() => selectedFieldIndex.value >= 0 ? fields.value[selectedFieldIndex.value] : null)

// select 字段的选项编辑器（key = 字段在数组中的索引）
const selectOptions = ref({})

const getFieldOptions = (index) => {
  if (!(index in selectOptions.value)) {
    selectOptions.value[index] = [
      { label: '选项1', value: 'option1' },
    ]
  }
  return selectOptions.value[index]
}

const addFieldOption = (index) => {
  const opts = getFieldOptions(index)
  opts.push({ label: `选项${opts.length + 1}`, value: `option${opts.length + 1}` })
}

const removeFieldOption = (index, optIndex) => {
  const opts = getFieldOptions(index)
  opts.splice(optIndex, 1)
}

const addField = (ft) => {
  if (ft.type === 'custom') {
    openCustomFieldDialog()
    return
  }
  if (ft.type === 'approver_teacher') {
    fields.value.push({
      field_label: '审批老师',
      field_name: 'approver_id',
      field_type: 'approver_teacher',
      required: true,
      default_value: '',
      sort_order: fields.value.length
    })
    selectedFieldIndex.value = fields.value.length - 1
    return
  }
  if (ft.type === 'file') {
    fields.value.push({
      field_label: '图片',
      field_name: `image_${Date.now()}`,
      field_type: 'file',
      required: false,
      default_value: '',
      sort_order: fields.value.length
    })
    selectedFieldIndex.value = fields.value.length - 1
    return
  }
  fields.value.push({
    field_label: ft.label,
    field_name: ft.label === '设备选择' ? 'equipment_id' : `field_${Date.now()}`,
    field_type: ft.type,
    required: true,
    default_value: '',
    sort_order: fields.value.length
  })
  selectedFieldIndex.value = fields.value.length - 1
}

const removeField = (index) => {
  fields.value.splice(index, 1)
  selectedFieldIndex.value = -1
}

// Step 3 Data
const flowNodes = ref([
  { name: '教师审批', type: 'approve', approver: null, condition: '' }
])

const addFlowNode = () => {
  ElMessageBox.prompt('请输入节点名称', '添加审批节点', {
    confirmButtonText: '确定',
    cancelButtonText: '取消',
    inputValue: '新审批环节'
  }).then(({ value }) => {
    flowNodes.value.push({ name: value, type: 'approve', approver: null, condition: '' })
  })
}

const removeFlowNode = (index) => {
  flowNodes.value.splice(index, 1)
}

// 节点编辑相关
const flowNodeDialogVisible = ref(false)
const editingNodeIndex = ref(-1)
const editingNode = reactive({ name: '', approver: null, condition: '' })
const availableApprovers = ref([])

const editFlowNode = async (index) => {
  editingNodeIndex.value = index
  const node = flowNodes.value[index]
  editingNode.name = node.name
  editingNode.approver = node.approver || null
  editingNode.condition = node.condition || ''
  flowNodeDialogVisible.value = true
  // 加载用户列表
  if (availableApprovers.value.length === 0) {
    try {
      const res = await api.getUsers()
      availableApprovers.value = res.data.results || res.data || []
    } catch (e) { /* ignore */ }
  }
}

const saveFlowNode = () => {
  if (editingNodeIndex.value < 0) return
  const node = flowNodes.value[editingNodeIndex.value]
  node.name = editingNode.name || node.name
  node.approver = editingNode.approver
  node.condition = editingNode.condition || ''
  flowNodeDialogVisible.value = false
}

// Step 4 Data
const rules = ref([])
const ruleDialogVisible = ref(false)
const currentRule = reactive({
  name: '',
  trigger_type: 'on_approve',
  action_type: 'send_message',
  message_content: '',
  action_config: null
})

const customFieldDialogVisible = ref(false)
const customField = reactive({
  label: '',
  name: '',
  type: 'text'
})

const openCustomFieldDialog = () => {
  Object.assign(customField, { label: '', name: '', type: 'text' })
  customFieldDialogVisible.value = true
}

const saveCustomField = () => {
  if (!customField.label || !customField.name) {
    return ElMessage.warning('请填写字段名称和字段编码')
  }
  fields.value.push({
    field_label: customField.label,
    field_name: customField.name,
    field_type: customField.type,
    required: true,
    default_value: '',
    sort_order: fields.value.length
  })
  selectedFieldIndex.value = fields.value.length - 1
  customFieldDialogVisible.value = false
}

const addRule = () => {
  Object.assign(currentRule, { 
    name: '新规则', 
    trigger_type: 'on_approve', 
    action_type: 'send_message',
    message_content: '您的申请已有新进展',
    action_config: null
  })
  ruleDialogVisible.value = true
}

const saveRule = () => {
  let config = {}
  if (currentRule.action_type === 'send_message') {
    config = { title: '业务通知', content: currentRule.message_content }
  } else if (currentRule.action_type === 'update_field') {
    config = { target: 'equipment', field: 'available_quantity', operator: '-', value: 1 }
  }
  
  rules.value.push({ 
    ...currentRule,
    action_config: config
  })
  ruleDialogVisible.value = false
}

const nextStep = () => {
  if (activeStep.value === 0 && (!appForm.name || !appForm.code)) {
    return ElMessage.warning('请填写应用名称和编码')
  }
  if (activeStep.value === 1 && fields.value.length === 0) {
    return ElMessage.warning('请至少添加一个表单字段')
  }
  activeStep.value++
}

const handlePublish = async () => {
  publishing.value = true
  try {
    // 1. 创建 App
    const appRes = await api.createLowCodeApp(appForm)
    const appId = appRes.data.id

    // 2. 创建 Form
    const formRes = await api.createLowCodeForm({
      app: appId,
      name: `${appForm.name}表单`,
      layout: { columns: 1 }
    })
    const formId = formRes.data.id

    // 3. 创建 Fields（含 select 字段的选项）
    for (const f of fields.value) {
      const fieldRes = await api.createLowCodeField({ ...f, form: formId })
      const fieldId = fieldRes.data?.id
      // 如果是 select 类型且有配置选项，为其创建 field_option 记录
      if (f.field_type === 'select' && fieldId) {
        const opts = selectOptions.value[fields.value.indexOf(f)]
        if (opts && opts.length > 0) {
          for (let i = 0; i < opts.length; i++) {
            await api.createLowCodeFieldOption({
              field_id: fieldId,
              value: opts[i].value || opts[i].label,
              label: opts[i].label,
              sort_order: i,
            })
          }
        }
      }
    }

    // 4. 创建 Flow（含节点审批人+条件）
    const nodes = [
      { node_id: 1, name: '提交申请', type: 'start', next: 2 }
    ]
    flowNodes.value.forEach((n, i) => {
      nodes.push({
        node_id: i + 2,
        name: n.name,
        type: 'approve',
        next: i + 3,
        approver: n.approver || null,  // 指定审批人ID（可选）
        condition: n.condition || '',  // 条件表达式，如 "days > 3"（可选）
      })
    })
    nodes.push({ node_id: flowNodes.value.length + 2, name: '结束', type: 'end', next: 0 })
    
    await api.createLowCodeFlow({
      app: appId,
      name: `${appForm.name}审批流`,
      nodes: nodes,
      is_active: true
    })

    // 5. 创建 Rules
    for (const r of rules.value) {
      await api.createLowCodeRule({
        app: appId,
        name: r.name,
        trigger_type: r.trigger_type,
        action_type: r.action_type,
        action_config: r.action_config || { title: '业务通知', content: `您的${appForm.name}申请已有新动态` },
        condition: r.condition || {}
      })
    }

    ElMessage.success('业务发布成功！')
    router.push('/')
  } catch (error) {
    console.error(error)
    let errorMsg = '发布失败，请检查配置'
    if (error.response?.data?.code) {
      errorMsg = '应用编码已存在，请返回第一步修改“应用编码”后重试'
    } else if (error.response?.data) {
      errorMsg = '发布失败：' + JSON.stringify(error.response.data)
    }
    ElMessage.error(errorMsg)
  } finally {
    publishing.value = false
  }
}
</script>

<style scoped>
.business-config-container { padding: 20px; }
.config-card { min-height: 500px; display: flex; flex-direction: column; }
.step-content { flex: 1; padding: 20px 0; }
.step-content.full-width { width: 100%; }
.card-footer { display: flex; justify-content: center; gap: 20px; border-top: 1px solid #eee; padding-top: 20px; }

.form-designer { display: flex; height: 400px; gap: 20px; }
.designer-left { width: 200px; border-right: 1px solid #eee; padding-right: 20px; }
